#include <iostream>
#include <vector>
using namespace std;

int main() {
    int H, W;
    cin >> H >> W;

    vector field(H + 2, string(W + 2, '.')); // すべて白マスの、上下左右に 1 列ずつ広げたマス目を用意する

    for (int i = 1; i <= H; ++i) {
        string S;
        cin >> S;
        field[i] = '.' + S + '.'; // 入力の左右に白マスを追加しておく
    }

    for (int i = 1; i <= H; ++i) {
        for (int j = 1; j <= W; ++j) { // すべてのマスについて
            int black_count = 0; // 周囲の黒マスの個数
            if (field[i - 1][j] == '#')
                ++black_count;
            if (field[i][j - 1] == '#')
                ++black_count;
            if (field[i][j + 1] == '#')
                ++black_count;
            if (field[i + 1][j] == '#')
                ++black_count;

            if (field[i][j] == '#' && black_count != 2 && black_count != 4) {
                // 条件を満たさないマスがあったら、No を出力して終了
                cout << "No" << endl;
                return 0;
            }
        }
    }

    // すべてのマスが条件を満たすので、Yes を出力して終了
    cout << "Yes" << endl;
    return 0;
}
